/* ==UserStyle==
@name ChatGPT Catppuccin
@namespace github.com/catppuccin/userstyles/styles/chatgpt
@homepageURL https://github.com/catppuccin/userstyles/tree/main/styles/chatgpt
@version 2026.11.06
@updateURL https://github.com/catppuccin/userstyles/raw/main/styles/chatgpt/catppuccin.user.less
@supportURL https://github.com/catppuccin/userstyles/issues?q=is%3Aopen+is%3Aissue+label%3Achatgpt
@description Soothing pastel theme for ChatGPT
@author Catppuccin
@license MIT

@preprocessor  less
@var select lightFlavor "Light Flavor" ["latte:Latte*", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha"]
@var select darkFlavor "Dark Flavor" ["latte:Latte", "frappe:Frappé", "macchiato:Macchiato", "mocha:Mocha*"]
@var select accentColor "Accent" ["rosewater:Rosewater", "flamingo:Flamingo", "pink:Pink", "mauve:Mauve*", "red:Red", "maroon:Maroon", "peach:Peach", "yellow:Yellow", "green:Green", "teal:Teal", "blue:Blue", "sapphire:Sapphire", "sky:Sky", "lavender:Lavender", "subtext0:Gray"]
==/UserStyle== */

@import "https://userstyles.catppuccin.com/lib/std/v1.less";

@-moz-document domain("chatgpt.com") {
  [data-theme="light"] {
    #catppuccin(@lightFlavor);
  }

  [data-theme="dark"] {
    #catppuccin(@darkFlavor);
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    --gray-0: @crust;
    --gray-25: @crust;
    --gray-50: @mantle;
    --gray-75: @mantle;
    --gray-100: @mantle;
    --gray-150: @base;
    --gray-200: @base;
    --gray-250: @surface0;
    --gray-300: @surface0;
    --gray-350: @surface1;
    --gray-400: @surface1;
    --gray-450: @surface2;
    --gray-500: @surface2;
    --gray-550: @overlay0;
    --gray-600: @overlay1;
    --gray-650: @overlay2;
    --gray-700: @subtext0;
    --gray-750: @subtext0;
    --gray-800: @subtext1;
    --gray-850: @subtext1;
    --gray-900: @text;
    --gray-925: @text;
    --gray-950: @text;
    --gray-975: @text;
    --gray-1000: @text;
    --white: @text;

    /* Surfaces */
    --app-color-background-surface: @base;
    --app-color-background-surface-under: @mantle;
    --app-color-background-editor-opaque: @mantle;
    --app-color-background-application-menu: @mantle;
    --app-color-background-control: @surface0;
    --app-color-background-elevated-primary: @surface0;
    --app-color-background-elevated-primary-opaque: @surface0;
    --app-color-background-elevated-secondary: @surface0;
    --app-color-background-elevated-secondary-opaque: @surface0;
    --app-color-background-elevated-tertiary-opaque: @mantle;
    --app-color-background-card: @surface0;
    --color-background-control-opaque: @surface0;
    --color-background-callout-surface: @surface1;
    --color-background-composer-action-bar: @surface1;
    --color-background-panel: @base;
    --color-surface-elevated-secondary: @surface0;

    /* Text and icons */
    --app-color-text-foreground: @text;
    --app-color-text-foreground-secondary: @subtext1;
    --app-color-text-foreground-tertiary: @subtext0;
    --app-color-foreground-application-menu: @text;
    --app-color-icon-primary: @text;
    --app-color-icon-secondary: @subtext1;
    --app-color-icon-tertiary: @subtext0;
    --app-color-icon-accent: @accent;
    --color-text-secondary: @subtext1;
    --color-text-header-upgrade: @accent;
    --text-status-error: @red;

    /* Statuses */
    .__status(@status, @color) {
      --color-text-@{status}: @color;
      --color-text-@{status}-solid: @base;
      --color-background-@{status}-solid: @color;
      --color-background-@{status}-solid-hover: lighten(@color, 5%);
      --color-background-@{status}-solid-active: darken(@color, 5%);
      --color-background-@{status}-soft-alpha: fade(@color, 15%);
      --color-background-@{status}-soft-alpha-hover: fade(@color, 20%);
      --color-background-@{status}-soft-alpha-active: fade(@color, 25%);
      --color-background-@{status}-surface: fade(@color, 10%);
      --color-border-@{status}-outline: @color;
    }

    .__status(info, @blue);
    .__status(danger, @red);
    .__status(success, @green);
    .__status(warning, @peach);
    .__status(caution, @yellow);
    .__status(discovery, @mauve);

    /* Borders */
    --app-color-border: @surface1;
    --app-color-border-light: @surface0;
    --app-color-border-heavy: @surface2;
    --app-color-border-focus: @accent;
    --app-color-border-application-menu-separator: @surface1;

    /* Buttons */
    --app-color-background-button-primary: @text;
    --app-color-background-button-primary-hover: @subtext1;
    --app-color-background-button-primary-active: @subtext0;
    --app-color-background-button-primary-inactive: @surface2;
    --app-color-text-button-primary: @base;
    --app-color-background-button-secondary: @surface0;
    --app-color-background-button-secondary-hover: @surface1;
    --app-color-background-button-secondary-active: @surface2;
    --app-color-background-button-secondary-inactive: @mantle;
    --app-color-text-button-secondary: @text;
    --app-color-background-button-tertiary: transparent;
    --app-color-background-button-tertiary-hover: @surface0;
    --app-color-background-button-tertiary-active: @surface1;
    --app-color-text-button-tertiary: @subtext0;
    --color-background-primary-solid: @accent;
    --color-background-primary-solid-hover: lighten(@accent, 5%);
    --color-background-primary-solid-active: darken(@accent, 5%);
    --color-text-primary-solid: @base;
    --color-text-neutral-solid: @base;
    --color-text-button-outline: @text;
    --color-border-button-outline: @surface1;
    --color-background-button-outline-hover: @surface0;

    /* Accent */
    --app-color-background-accent: fade(@accent, 15%);
    --app-color-background-accent-hover: fade(@accent, 20%);
    --app-color-background-accent-active: fade(@accent, 25%);
    --app-color-text-accent: @accent;
    --app-color-text-on-accent: @base;
    --color-accent: @accent;
    --color-background-accent-solid: @accent; // enabled toggle switches
    --color-background-accent-ghost-hover: fade(@accent, 15%);
    --link-primary-text-color: @accent; // links in settings
    --color-text-accent: @accent;
    --color-text-accent-hover: lighten(@accent, 5%);
    --color-text-on-accent: @base;
    --color-text-accent-solid: @base;
    --color-token-on-accent: @base;
    --color-button-accent: @accent;
    --color-button-accent-hover: lighten(@accent, 5%);
    --color-button-accent-active: darken(@accent, 5%);
    --color-ring: @accent;
    --color-background-text-selection: fade(@accent, 25%);
    --color-background-attribution-highlight: fade(@accent, 25%);

    /* Chat/composer */
    --color-background-composer-primary: @accent;
    --color-text-composer-primary: @base;
    --color-text-composer-reference: @accent;
    --color-background-user-message: fade(@accent, 15%);
    --color-text-user-message: @text;
    --color-background-user-message-compact: @surface0;

    /* Mode toggle */
    --color-background-mode-toggle-track: @mantle;
    --color-background-mode-toggle-selected: @surface0;
    --color-border-mode-toggle-selected: @surface1;
    --color-text-mode-toggle-primary: @text;
    --color-text-mode-toggle-inactive: @subtext0;
    --color-text-mode-toggle-accent: @accent;

    /* Diffs */
    --app-color-decoration-added: @green;
    --app-color-decoration-deleted: @red;
    --app-color-editor-added: fade(@green, 20%);
    --app-color-editor-deleted: fade(@red, 20%);

    /* Color ramps */
    .__ramp(@hue, @color) {
      --@{hue}-25: lighten(@color, 10%);
      --@{hue}-50: lighten(@color, 10%);
      --@{hue}-75: lighten(@color, 10%);
      --@{hue}-100: lighten(@color, 10%);
      --@{hue}-200: lighten(@color, 5%);
      --@{hue}-300: lighten(@color, 5%);
      --@{hue}-400: @color;
      --@{hue}-500: darken(@color, 5%);
      --@{hue}-600: darken(@color, 5%);
      --@{hue}-700: darken(@color, 10%);
      --@{hue}-800: darken(@color, 10%);
      --@{hue}-900: darken(@color, 10%);
    }

    .__ramp(blue, @blue);
    .__ramp(red, @red);
    .__ramp(green, @green);
    .__ramp(orange, @peach);
    .__ramp(yellow, @yellow);
    .__ramp(purple, @mauve);

    /* Syntax highlighting */
    --color-codex-syntax-keyword: @mauve;
    --color-codex-syntax-string: @green;
    --color-codex-syntax-comment: @overlay2;
    --color-codex-syntax-literal: @peach; // numbers, literals and builtins
    --color-codex-syntax-variable: @text; // includes function names, but using blue makes all variable names blue as well
    --color-codex-syntax-name: @red; // includes symbols
    --color-codex-syntax-attribute: @yellow;
    --color-codex-syntax-error: @red;

    /* Code blocks */
    &[data-code-block],
    [class*="CodeBlockPlaceholder-"] {
      --color-background-secondary-soft-alpha: @mantle;
    }

    /* New chat suggestions */
    [class*="home-suggestion-list-item"] img {
      filter: @subtext0-filter;
    }
  }
}

@-moz-document domain("auth.openai.com") {
  :root {
    @media (prefers-color-scheme: light) {
      #catppuccin(@lightFlavor);
    }
    @media (prefers-color-scheme: dark) {
      #catppuccin(@darkFlavor);
    }
  }

  #catppuccin(@flavor) {
    #lib.palette();
    #lib.defaults();

    color: @text;

    background-color: @base;
    --main-page-background: @base;

    // Logo
    a[href="https://chatgpt.com"] > svg {
      filter: @text-filter;
    }

    --text-primary: @text;
    --text-secondary: @subtext1;
    --text-tertiary: @subtext0;
    --text-placeholder: @subtext0; // form field labels above the input (e.g. "Email" and "Password")

    --accent-blue: @accent;
    --link: @accent;

    --border-medium: @surface2;

    --button-primary-background: @text;
    --button-primary-hover: @subtext1;
    --button-text-on-primary: @base;

    --button-outline-hover: @surface0;

    --gray-100: @surface2; // divider lines

    input {
      color: @text;
    }

    [class*="_toggleVisibilityButton"]:where(:hover, :focus-visible)::before {
      background-color: @surface0;
    }

    [data-overlay-container] [class*="_tooltip"] {
      --tooltip-background-color: @mantle !important;
      --tooltip-color: @text !important;
    }
  }
}

